import{_ as i,l,o as e,c as s,v as r,p as n,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"范式与分解","description":"","frontmatter":{"title":"范式与分解","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/normal-forms.md","filePath":"cs/normal-forms.md","lastUpdated":1789023840000}'),c={name:"cs/normal-forms.md"};function m(E,a,_,F,N,f){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="范式与分解" tabindex="-1">范式与分解 <a class="header-anchor" href="#范式与分解" aria-label="Permalink to &quot;范式与分解&quot;">​</a></h1><div class="epigraph"><p>异常来自把不同事实塞进同一关系；分解按函数依赖切开，连接再拼回。</p><footer>—— 据 Codd 对 3NF；Codd, Further Normalization, 1972；Bernstein 对合成算法的整理</footer></div><p><a href="/cs/predicate-pushdown">上一课</a>在查询树上做等价变换。本课不改某一条 SQL。缺口是：模式本身若把多个独立事实捆在一行，更新会出现插入、删除、修改异常。范式用函数依赖判断「这张表是否太宽」；分解给出更窄的关系，用连接恢复。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/keys-integrity">键</a>已经能识别元组。若非主属性依赖键的真子集（部分依赖），或依赖其他非主属性（传递依赖），同一事实会重复出现，删一行可能丢掉无关事实。缺口不是新的查询语言，而是模式设计：1NF 禁止表中表；2NF 去掉部分依赖；3NF / BCNF 处理传递与键侧的依赖。</p><p>本课不把「永远 BCNF」写成教条。有的依赖集无法既保依赖又保无损连接又落在 BCNF；3NF 合成是常用折中。</p><p><span class="marginnote">无损连接：分解后的自然连接能恢复原关系。依赖保持：原有函数依赖仍能在单个分解后的关系上检查，而不必先连接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定属性集 \\(U\\) 与函数依赖集 \\(F\\)。用闭包判断候选键。若违反目标范式，分解成投影，使每一投影满足范式，且分解无损。3NF 合成按 \\(F\\) 的正则覆盖建表；BCNF 分解沿违反依赖切开。本课不把多值依赖与 4NF 写进主干，只点名它们存在。</p>',9)),(e(),n(h,null,{default:t(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FD%5B%22%E5%87%BD%E6%95%B0%E4%BE%9D%E8%B5%96%20F%22%5D%20--%3E%20KEY%5B%22%E5%80%99%E9%80%89%E9%94%AE%22%5D%0A%20%20FD%20--%3E%20NF%5B%222NF%20%2F%203NF%20%2F%20BCNF%22%5D%0A%20%20NF%20--%3E%20DEC%5B%22%E6%97%A0%E6%8D%9F%E5%88%86%E8%A7%A3%22%5D%0A%20%20DEC%20--%3E%20VIEW%5B%22%E5%90%8E%E8%AF%BE%3A%20%E8%A7%86%E5%9B%BE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分解之后，更新局部化：改一处事实只碰一张表。查询则可能要多做连接——这正是前几课计划和代价要付的账。所以规范化是逻辑设计，不是「查询一定更快」。反规范化是故意保留冗余换少连接，完整性改由应用或触发器补；主干把这标成权衡，不标成另一套模型。</p><p><a href="/cs/relational-algebra">关系代数</a>的连接这时从「查询写法」变成「模式恢复」：分解的正确性条件就是那次连接无损。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 ER 图作图法，不把范式当成文件分片。也不处理时态、XML、文档模型的「嵌套是否 1NF」。NULL 与弱实例理论不展开。后课视图可以让用户仍看见「宽表」，底下是分解后的关系。</p><p>依赖必须声明或从数据里发现；本课假定 \\(F\\) 已给定。后课默认：谈到基表，依赖已尽量收进 3NF/BCNF 权衡；宽行若出现，是显式反规范，不是没学过依赖。</p><p>分解后的模式仍是关系模型里的关系，只是更窄。查询变多连接，正是前几课计划要付的账，不是范式失败。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>改写动查询树；本课按函数依赖分解模式。</li><li>无损与保依赖是分解的正确性条件，不是审美。</li><li>视图如何挡住分解后的碎片，是后课缺口。</li><li>出处：Codd, 1972；Date；Ramakrishnan and Gehrke。</li></ul>',9))])}const A=i(c,[["render",m]]);export{B as __pageData,A as default};
